function validate([n, k]) {
  if (!Number.isInteger(n) || !Number.isInteger(k)) return 'n and k must be integers.';
  if (n < 1 || n > 1000) return 'n is between 1 and 1000.';
  if (k < 1 || k > n) return 'k is between 1 and n.';
  return null;
}

