function waysToDistribute(n, k) {
  const MOD = 1e9 + 7;
  const dp = Array.from({ length: n + 1 }, () => new Array(k + 1).fill(0));
  dp[0][0] = 1;

  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= Math.min(i, k); j++) {
      const newBag = dp[i - 1][j - 1];
      const joinBag = (j * dp[i - 1][j]) % MOD;
      dp[i][j] = (newBag + joinBag) % MOD;
    }
  }
  return dp[n][k];
}

