function waysToDistribute(n, k) {
  // Count the onto assignments of n candies to k labelled bags by inclusion-exclusion,
  // then divide by k! because the bags are interchangeable. Exact BigInt arithmetic throughout.
  let onto = 0n;
  let choose = 1n;
  for (let i = 0; i <= k; i++) {
    const term = choose * BigInt(k - i) ** BigInt(n);
    onto += i % 2 === 0 ? term : -term;
    choose = choose * BigInt(k - i) / BigInt(i + 1);
  }
  let factorial = 1n;
  for (let i = 2; i <= k; i++) factorial *= BigInt(i);
  return Number((onto / factorial) % 1000000007n);
}

